        if not arg.startswith('-'):
            if opts['file'] is None: opts['file'] = arg
            else:
                print(f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
            i += 1
