            print(HELP_TEXT)
            sys.exit(0)
        if arg in ('-V', '--version'):
            print("csview 1.3.4")
            sys.exit(0)

        if arg == '-H' or arg == '--no-headers': opts['H'] = True
        elif arg == '-n' or arg == '--number': opts['n'] = True
        elif arg == '-t' or arg == '--tsv': opts['t'] = True
        elif arg == '-P' or arg == '--disable-pager': opts['P'] = True
        elif arg == '-d' or arg == '--delimiter': opts['d'] = take_val('--delimiter')
        elif arg == '-s' or arg == '--style': opts['s'] = take_val('--style')
        elif arg == '-p' or arg == '--padding': opts['p'] = int(take_val('--padding'))
        elif arg == '-i' or arg == '--indent': opts['i'] = int(take_val('--indent'))
        elif arg == '--sniff': opts['sniff'] = int(take_val('--sniff'))
        elif arg == '--header-align': opts['header_align'] = take_val('--header-align')
        elif arg == '--body-align': opts['body_align'] = take_val('--body-align')
        elif arg.startswith('--'):
            if '=' in arg:
                k, v = arg.split('=', 1)
                if k == '--delimiter': opts['d'] = v
                elif k == '--style': opts['s'] = v
                elif k == '--padding': opts['p'] = int(v)
                elif k == '--indent': opts['i'] = int(v)
                elif k == '--sniff': opts['sniff'] = int(v)
                elif k == '--header-align': opts['header_align'] = v
                elif k == '--body-align': opts['body_align'] = v
                else:
                    print(f"error: unexpected argument '{k}' found\n\n  tip: to pass '{k}' as a value, use '-- {k}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
            else:
                print(f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
        else:
            j = 1
            while j < len(arg):
                ch = arg[j]
                if ch == 'H': opts['H'] = True
                elif ch == 'n': opts['n'] = True
                elif ch == 't': opts['t'] = True
                elif ch == 'P': opts['P'] = True
                elif ch == 'd':
                    if j + 1 < len(arg): opts['d'] = arg[j+1:]; break
                    else: opts['d'] = take_val('-d'); break
                elif ch == 's':
                    if j + 1 < len(arg): opts['s'] = arg[j+1:]; break
                    else: opts['s'] = take_val('-s'); break
                elif ch == 'p':
                    if j + 1 < len(arg): opts['p'] = int(arg[j+1:]); break
                    else: opts['p'] = int(take_val('-p')); break
                elif ch == 'i':
                    if j + 1 < len(arg): opts['i'] = int(arg[j+1:]); break
                    else: opts['i'] = int(take_val('-i')); break
                else:
                    print(f"error: unexpected argument '-{ch}' found\n\n  tip: to pass '-{ch}' as a value, use '-- -{ch}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
                j += 1
        i += 1

    if opts['t']:
        for a in sys.argv[1:]:
            if a == '-d' or a.startswith('-d') and len(a)>2 or a == '--delimiter' or a.startswith('--delimiter='):
                print("error: the argument '--tsv' cannot be used with '--delimiter <DELIMITER>'\n\nUsage: executable --tsv <FILE>\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
