    'none': (None, None, None, None, ("", "", "")),
    'ascii': (("+", "-", "+", "+"), ("+", "-", "+", "+"), None, ("+", "-", "+", "+"), ("|", "|", "|")),
    'ascii2': (None, (" ", "-", "+", " "), None, None, (" ", "|", " ")),
    'sharp': (("┌", "─", "┬", "┐"), ("├", "─", "┼", "┤"), None, ("└", "─", "┴", "┘"), ("│", "│", "│")),
    'rounded': (("╭", "─", "┬", "╮"), ("├", "─", "┼", "┤"), None, ("╰", "─", "┴", "╯"), ("│", "│", "│")),
    'reinforced': (("┏", "─", "┬", "┓"), ("├", "─", "┼", "┤"), None, ("┗", "─", "┴", "┛"), ("│", "│", "│")),
    'markdown': (None, ("|", "-", "|", "|"), None, None, ("|", "|", "|")),
    'grid': (("┌", "─", "┬", "┐"), ("├", "─", "┼", "┤"), ("├", "─", "┼", "┤"), ("└", "─", "┴", "┘"), ("│", "│", "│"))
