    cat = unicodedata.category(c)
    if cat in ('Cc', 'Cf', 'Mn', 'Me', 'Zl', 'Zp'):
        return 0
    return 2 if unicodedata.east_asian_width(c) in ('W', 'F') else 1

def str_width(s):
    return sum(char_width(c) for c in s)

def trunc_pad(s, max_w, align):
    cur_w = 0
    out = ""
    for c in s:
        cw = char_width(c)
        if cur_w + cw > max_w:
            break
        out += c
        cur_w += cw

    diff = max_w - cur_w
    if diff == 0:
        return out

    if align == 'left':
        left = 0
        right = diff
    elif align == 'right':
        left = diff
        right = 0
    else: # center
        left = diff // 2
        right = diff - left

    return (" " * left) + out + (" " * right)

file_path = opts['file']
fd = sys.stdin if file_path is None else None

