        print(f"csview: No such file or directory (os error 2)", file=sys.stderr)
        sys.exit(1)

reader = csv.reader(fd, delimiter=opts['d'])
records = []

try:
    for row in reader:
        records.append(row)
except csv.Error as e:
    # Mimic rust csv error. We'll just do something generic or exact if we know.
    print(f"csview: CSV error: {e}", file=sys.stderr)
    sys.exit(1)

if not records:
    # empty file
    widths = []
else:
    # check uneven rows matching csv crate default behavior
    first_len = len(records[0])
    for i, row in enumerate(records):
