        write_out(" " * opts['i'] + style[4][0] + style[4][2] + "\n")
        write_line(style[3])
    else:
        write_line(style[0])
        for r_idx, row in enumerate(records):
            if r_idx > 0:
                if not opts['H'] and r_idx == 1:
                    write_line(style[1])
                else:
                    write_line(style[2])
            write_row(r_idx, row)
        write_line(style[3])
finally:
    if pager_proc:
        try:
            output_fd.close()
            pager_proc.wait()
        except:
            pass
