    print(f"csview: CSV error: {e}", file=sys.stderr)
    sys.exit(1)

# Handle line numbers immediately
if opts['n']:
    if not opts['H']:
        if records:
            records[0].insert(0, "#")
        for i in range(1, len(records)):
            records[i].insert(0, str(i))
    else:
        for i in range(len(records)):
            records[i].insert(0, str(i+1))

if not records:
    widths = []
else:
    first_len = len(records[0])
    for i, row in enumerate(records):
        if len(row) != first_len:
            print(f"csview: CSV error: record {i} (line: {i+1}, byte: 0): found record with {len(row)} fields, but the previous record has {first_len} fields", file=sys.stderr)
            sys.exit(1)

    if opts['sniff'] == 0:
        sniff_records = records
    else:
        n_sniff = opts['sniff']
        if not opts['H']:
            n_sniff += 1
        sniff_records = records[:n_sniff]

    cols = len(records[0])
    widths = [0] * cols
    for row in sniff_records:
        for i in range(cols):
            w = str_width(row[i])
            if w > widths[i]:
                widths[i] = w

style = STYLES[opts['s']]

pager_proc = None
output_fd = sys.stdout

if not opts['P'] and os.isatty(sys.stdout.fileno()):
    if 'LESS' not in os.environ:
        os.environ['LESS'] = '-SF'
    try:
        pager_proc = subprocess.Popen(['less'], stdin=subprocess.PIPE, text=True, encoding='utf-8')
        output_fd = pager_proc.stdin
    except:
        pass

def write_out(text):
    try:
        output_fd.write(text)
    except IOError:
        pass

def write_line(line_def):
    if not line_def: return
    write_out(" " * opts['i'])
    write_out(line_def[0])
    for i, w in enumerate(widths):
        if i > 0:
            write_out(line_def[2])
        cell_w = opts['p'] * 2 + w
        write_out(line_def[1] * cell_w)
    write_out(line_def[3] + "\n")

def write_row(row_idx, row_data):
    write_out(" " * opts['i'])
    row_def = style[4]

    pad_str = " " * opts['p']

    is_header = (not opts['H'] and row_idx == 0)
    align = opts['header_align'] if is_header else opts['body_align']

    if opts['s'] == 'none' and opts['p'] == 0:
        # Special case for none style with 0 padding where left, sep, right are empty
        for i, cell in enumerate(row_data):
            write_out(trunc_pad(cell, widths[i], align))
        write_out("\n")
        return

    write_out(row_def[0])

    for i, cell in enumerate(row_data):
        if i > 0:
            write_out(row_def[1])
        write_out(pad_str)
        write_out(trunc_pad(cell, widths[i], align))
        write_out(pad_str)

    write_out(row_def[2] + "\n")

try:
    if not records:
        write_line(style[0])
        write_out(" " * opts['i'] + style[4][0] + (" " * (opts['p']*2)) + style[4][2] + "\n" if style[4][0] else "\n")
